package com.styleshop.product.repository;
import com.styleshop.product.model.Product; import jakarta.persistence.criteria.Predicate; import org.springframework.boot.autoconfigure.condition.ConditionalOnProperty; import org.springframework.data.domain.*; import org.springframework.data.jpa.domain.Specification; import org.springframework.stereotype.Repository; import java.math.BigDecimal; import java.util.*;
@Repository @ConditionalOnProperty(name="styleshop.product-dao",havingValue="jpa") public class JpaProductDataSource implements ProductDataSource {private final JpaProductRepository repo; public JpaProductDataSource(JpaProductRepository r){repo=r;} public Page<Product> search(String k,Long c,BigDecimal min,BigDecimal max,Pageable p){Specification<Product>s=(root,q,cb)->{List<Predicate>x=new ArrayList<>();if(k!=null&&!k.isBlank()){String v="%"+k.toLowerCase()+"%";x.add(cb.or(cb.like(cb.lower(root.get("name")),v),cb.like(cb.lower(root.get("description")),v)));}if(c!=null)x.add(cb.equal(root.get("category").get("id"),c));if(min!=null)x.add(cb.greaterThanOrEqualTo(root.get("price"),min));if(max!=null)x.add(cb.lessThanOrEqualTo(root.get("price"),max));return cb.and(x.toArray(Predicate[]::new));};return repo.findAll(s,p);} public Optional<Product> findById(Long id){return repo.findById(id);}public Product save(Product p){return repo.save(p);}public void deleteById(Long id){repo.deleteById(id);}public String name(){return "JPA";}}
